def parse_port(port_str: str) -> int:
    try:
        port = int(port_str)
        if not (1 <= port <= 65535):
            raise ValueError(f'Port {port} out of range (1-65535)')
        return port
    except ValueError as exc:
        print(f'Validation failed: {exc}')
        return 8000

print('Port 1:', parse_port('9000'))
print('Port 2:', parse_port('invalid'))

def run_task(success: bool) -> str:
    log = []
    try:
        log.append('try')
        if not success:
            raise RuntimeError('boom')
    except RuntimeError:
        log.append('caught')
    else:
        log.append('success')
    finally:
        log.append('cleanup')
    return ' -> '.join(log)

print(run_task(True))
print(run_task(False))

