def boundary_handler(task_func, task_id: str) -> dict:
    try:
        result = task_func()
        return {'status': 'ok', 'task_id': task_id, 'result': result}
    except Exception as exc:
        # In real services: logging.exception('Task failed')
        return {'status': 'error', 'task_id': task_id, 'error_type': type(exc).__name__, 'detail': str(exc)}

print(boundary_handler(lambda: 100 // 2, 'task_1'))
print(boundary_handler(lambda: 100 // 0, 'task_2'))

def safe_divide(a: float, b: float) -> float:
    try:
        return a / b
    except ZeroDivisionError:
        return float('inf')

